import{_ as a,o as l,c as e,a as i}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"技能考核路线图","description":"","frontmatter":{},"headers":[],"relativePath":"skill-roadmap.md","filePath":"skill-roadmap.md","lastUpdated":1787278345000}'),d={name:"skill-roadmap.md"};function r(o,t,s,n,h,p){return l(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="技能考核路线图" tabindex="-1">技能考核路线图 <a class="header-anchor" href="#技能考核路线图" aria-label="Permalink to &quot;技能考核路线图&quot;">​</a></h1><h2 id="先选职业方向" tabindex="-1">先选职业方向 <a class="header-anchor" href="#先选职业方向" aria-label="Permalink to &quot;先选职业方向&quot;">​</a></h2><p>四级/中级工报名时需选择职业方向。两个方向共享理论基础和“设施操作、设施保养”训练，但职业功能范围不同：</p><table tabindex="0"><thead><tr><th>方向</th><th>标准职业功能</th><th>训练重点</th></tr></thead><tbody><tr><td>消防设施监控操作</td><td>设施监控、设施操作、设施保养</td><td>消防控制室值班监控、报警信息识别与处置、联动控制、常用设施操作和日常保养</td></tr><tr><td>消防设施检测维修保养</td><td>设施操作、设施保养、设施维修、设施检测</td><td>常用设施操作与保养、故障判断与处理、检测方案执行、仪器使用、结果记录</td></tr></tbody></table><blockquote><p>依据：《消防设施操作员国家职业技能标准（2019年版）》；具体考核项目、分值、顺序和现场评分表以报考地鉴定站当批次公告为准。本站不把“训练清单”宣称为全国统一题卡。</p></blockquote><h2 id="你的考试主线-检测维修保养" tabindex="-1">你的考试主线：检测维修保养 <a class="header-anchor" href="#你的考试主线-检测维修保养" aria-label="Permalink to &quot;你的考试主线：检测维修保养&quot;">​</a></h2><p>这不是把四个职业功能并列背诵，而是一条逐步加深的学习链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先看懂状态</span></span>
<span class="line"><span>→ 再按任务操作</span></span>
<span class="line"><span>→ 再按项目保养</span></span>
<span class="line"><span>→ 再按现象维修</span></span>
<span class="line"><span>→ 最后按方案检测和判定</span></span></code></pre></div><p>每进入下一阶段，都要把上一阶段的内容带过来。例如，学习“检测”时仍然要用到控制器状态识别、操作安全、故障分层和记录方法。这样学完后，面对一个设备异常，不会只会背单个按钮，而能解释完整原因和处理边界。</p><h3 id="五阶段学习检查" tabindex="-1">五阶段学习检查 <a class="header-anchor" href="#五阶段学习检查" aria-label="Permalink to &quot;五阶段学习检查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>学完应会</th><th>不会时回看</th><th>进入下一阶段条件</th></tr></thead><tbody><tr><td>设施监控基础</td><td>区分火警、故障、监管、屏蔽/隔离，并说明信息来源</td><td><a href="/skill/01-monitoring">设施监控</a>、<a href="/theory/06-fire-facilities">消防设施基础</a>、S01</td><td>能从控制器信息追到现场核实、报告、复位和恢复</td></tr><tr><td>设施操作</td><td>说清控制方式、现场动作、反馈和恢复，不把动作当成合格</td><td><a href="/skill/02-operation">设施操作</a>、S02、S19-S22</td><td>能口述至少一个报警、一个水系统、一个其他设施的完整六步</td></tr><tr><td>设施保养</td><td>按外观、连接、状态、功能、记录组织检查，发现异常不隐瞒</td><td><a href="/skill/03-maintenance">设施保养</a>、<a href="/theory/10-safety-health">安全生产</a>、S03、S15-S18</td><td>能区分保养发现、维修处理、检测判定三种记录目的</td></tr><tr><td>设施维修</td><td>从现象分层判断，落实隔离，处理后复测并报告</td><td><a href="/skill/04-repair">设施维修</a>、<a href="/theory/05-electrical-fire">电气消防</a>、S04、S07-S10</td><td>能完成现象—影响—原因假设—处理—验证—报告闭环</td></tr><tr><td>设施检测</td><td>按方案记录输入、显示、动作、反馈、恢复和判定依据</td><td><a href="/skill/05-detection">设施检测</a>、<a href="/theory/09-laws-standards">法律法规与技术标准</a>、S05、S11-S14</td><td>能说明检测方法、仪器、原始值、复测和依据版本，且不写死未核验阈值</td></tr></tbody></table><blockquote><p>如果某阶段只能复述名词，不能说明“为什么、看什么、异常怎么办、如何恢复”，就先不要进入下一阶段。</p></blockquote><h3 id="综合复习路径" tabindex="-1">综合复习路径 <a class="header-anchor" href="#综合复习路径" aria-label="Permalink to &quot;综合复习路径&quot;">​</a></h3><ol><li><strong>按理论章复习</strong>：十章各选一张 T 题，写出“理论原理→设备行为→安全/记录要求”；</li><li><strong>按设备复习</strong>：报警系统、水系统、其他消防设施分别完成“组成—正常—动作—反馈—故障—恢复”；</li><li><strong>按职业功能复习</strong>：用同一设备连续复述操作、保养、维修、检测四种任务的区别；</li><li><strong>按混合场景复习</strong>：使用 S23-S25，并回看对应 S26-S49 设备专项题，先判断影响和授权，再判断处理；</li><li><strong>按依据收口</strong>：涉及数值、动作时间、允许误差、权限或地方考核时，回查适用标准、方案、说明书和当批次评分表。</li></ol><p>建议把技能学习时间按以下优先级安排：</p><table tabindex="0"><thead><tr><th>优先级</th><th>学习内容</th><th>你要达到的结果</th></tr></thead><tbody><tr><td>1</td><td>设施监控基础</td><td>能识别控制器状态，读懂火警、故障、监管和屏蔽/隔离信息</td></tr><tr><td>2</td><td>设施操作</td><td>能按任务确认控制方式，观察现场动作和反馈，并恢复规定状态</td></tr><tr><td>3</td><td>设施保养</td><td>能按外观、连接、状态、功能、记录五类项目组织检查</td></tr><tr><td>4</td><td>设施维修</td><td>能描述故障现象，提出安全隔离、处理、验证和报告闭环</td></tr><tr><td>5</td><td>设施检测</td><td>能按方案记录输入、显示、动作、反馈、恢复和最终判定</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">记忆主线</p><p>把每个设施都按同一套问题学习：<strong>它是什么？检查什么？怎样触发或操作？应该看到什么？异常怎么办？结束后恢复什么？记录什么？</strong></p></div><h2 id="零基础必练清单" tabindex="-1">零基础必练清单 <a class="header-anchor" href="#零基础必练清单" aria-label="Permalink to &quot;零基础必练清单&quot;">​</a></h2><h3 id="两个方向都要练" tabindex="-1">两个方向都要练 <a class="header-anchor" href="#两个方向都要练" aria-label="Permalink to &quot;两个方向都要练&quot;">​</a></h3><ul><li>火灾报警控制器、消防联动控制器：正常监视、火警、故障、监管、屏蔽/隔离、主电/备电、手动/自动状态识别。</li><li>报警信息处置：消音、信息查询、现场核实、报告、复位和恢复确认。</li><li>消防泵组、消火栓系统：控制方式、启停、主备切换、压力/反馈观察。</li><li>防烟排烟系统：风机、风阀、排烟口/送风口的控制、动作和反馈。</li><li>防火门、防火卷帘：状态识别、控制、现场安全确认和反馈核对。</li><li>消防应急广播、消防电话、消防应急照明和疏散指示：分区、启动、反馈、恢复。</li><li>火灾自动报警系统、自动灭火系统及其他常用设施的外观检查、清洁、状态确认和记录。</li><li>操作结束后的自动/联动/监视状态恢复，以及异常报告和记录填写。</li></ul><h3 id="监控操作方向加练" tabindex="-1">监控操作方向加练 <a class="header-anchor" href="#监控操作方向加练" aria-label="Permalink to &quot;监控操作方向加练&quot;">​</a></h3><ul><li>消防控制室值班监控和运行记录。</li><li>报警、故障、监管、屏蔽等信息的分类、核实、处置和升级报告。</li><li>联动控制盘、图形显示装置、消防电话和应急广播的协同使用。</li></ul><h3 id="检测维修保养方向加练" tabindex="-1">检测维修保养方向加练 <a class="header-anchor" href="#检测维修保养方向加练" aria-label="Permalink to &quot;检测维修保养方向加练&quot;">​</a></h3><ul><li>按检测方案核对对象、范围、仪器、校准状态和安全隔离。</li><li>常见探测器、手动报警按钮、模块、主备电、回路和通信故障的现象—判断—处理—验证闭环。</li><li>消防设施检测项目的触发、显示、动作、反馈、复位和结果记录。</li><li>维修、更换或恢复前后的停用审批、临时防护、功能确认和记录。</li></ul><h2 id="统一操作与评分模板" tabindex="-1">统一操作与评分模板 <a class="header-anchor" href="#统一操作与评分模板" aria-label="Permalink to &quot;统一操作与评分模板&quot;">​</a></h2><p>每个项目至少完成以下六步，并能口述依据：</p><ol><li><strong>对象确认</strong>：确认设备名称、地址/区域、场景和任务要求。</li><li><strong>安全确认</strong>：确认人员安全、控制方式、联动影响、授权和必要的隔离措施。</li><li><strong>规范操作</strong>：按设备说明书、单位规程和鉴定站评分表执行。</li><li><strong>结果观察</strong>：核对现场动作、控制器显示、反馈信号、异常信息和必要的测量结果。</li><li><strong>恢复状态</strong>：按要求复位，恢复自动/联动/监视或其他规定状态；不能恢复时立即报告。</li><li><strong>记录报告</strong>：记录时间、对象、现象、操作、结果、异常、临时措施和报告对象。</li></ol><h2 id="关键技能与安全红线" tabindex="-1">关键技能与安全红线 <a class="header-anchor" href="#关键技能与安全红线" aria-label="Permalink to &quot;关键技能与安全红线&quot;">​</a></h2><p>标准中标注“★”的技能涉及安全生产或核心操作。训练时不得：</p><ul><li>为消除故障提示而直接拔线、短接、屏蔽或关闭电源；</li><li>未确认区域安全就启动泵、风机、卷帘或其他联动设备；</li><li>未断电、验电、隔离就拆装电气部件；</li><li>将复位当成排除故障，或把“设备动作”当成“系统功能合格”；</li><li>未恢复规定状态、未记录或未报告就结束作业。</li></ul><blockquote><p>现场实操必须在鉴定站或有资质人员指导下进行。技能考核方式、关键技能分值门槛和不合格判定，以报考地当批次实施细则为准。</p></blockquote>`,31)])])}const u=a(d,[["render",r]]);export{b as __pageData,u as default};
